#include <algorithm>
#include <cstdint>
#include <iostream>
#include <unordered_map>
#include <vector>

using namespace std;

using Lint = long long;

const int MAXN = 2020;
const int MAXM = 420;

int a, b, c, m;
bool used[MAXN];
vector<int> primes;
unordered_map<uint64_t, int> memo[MAXM];

int mul(int x, int y) {
    return static_cast<int>((static_cast<Lint>(x) * y) & m);
}

int add(int x, int y) {
    return (x + y) & m;
}

uint64_t makeKey(int x, int y, int z) {
    return (static_cast<uint64_t>(x) * 2001 + y) * 2001 + z;
}

Lint f(int x, int y, int z, int n) {
    if (n >= static_cast<int>(primes.size())) {
        return 1;
    }

    const uint64_t key = makeKey(x, y, z);
    auto it = memo[n].find(key);
    if (it != memo[n].end()) {
        return it->second;
    }

    int ret = 0;
    const int p = primes[n];

    for (int i = 0, vx = x; vx; vx /= p, ++i) {
        for (int j = 0, vy = y; vy; vy /= p, ++j) {
            for (int k = 0, vz = z; vz; vz /= p, ++k) {
                ret = add(ret, mul(static_cast<int>(f(vx, vy, vz, n + 1)),
                                   i + j + k + 1));
            }
        }
    }

    memo[n].emplace(key, ret);
    return ret;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> a >> b >> c;

    m = (1 << 30) - 1;

    for (int i = 2; i <= 2000; ++i) {
        if (used[i]) {
            continue;
        }

        primes.push_back(i);
        for (int j = i; j <= 2000; j += i) {
            used[j] = true;
        }
    }

    reverse(primes.begin(), primes.end());

    cout << f(a, b, c, 0) << '\n';
    return 0;
}

#include <algorithm>
#include <cstdint>
#include <iostream>
#include <unordered_map>
#include <vector>

using namespace std;

const int MAX_VALUE = 2000;

int a, b, c;
int maskValue;
bool composite[MAX_VALUE + 1];
vector<int> primes;
vector<unordered_map<uint64_t, int>> memo;

int mul(int x, int y) {
    return static_cast<int>((1LL * x * y) & maskValue);
}

int add(int x, int y) {
    return (x + y) & maskValue;
}

uint64_t encode(int x, int y, int z) {
    return (static_cast<uint64_t>(x) * 2001 + y) * 2001 + z;
}

int f(int x, int y, int z, int n) {
    while (n < static_cast<int>(primes.size()) &&
           primes[n] > max(x, max(y, z))) {
        ++n;
    }

    if (n == static_cast<int>(primes.size())) {
        return 1;
    }

    uint64_t key = encode(x, y, z);
    auto it = memo[n].find(key);
    if (it != memo[n].end()) {
        return it->second;
    }

    int result = 0;
    int p = primes[n];

    for (int i = 0, vx = x; vx; vx /= p, ++i) {
        for (int j = 0, vy = y; vy; vy /= p, ++j) {
            for (int k = 0, vz = z; vz; vz /= p, ++k) {
                result = add(result, mul(f(vx, vy, vz, n + 1),
                                         i + j + k + 1));
            }
        }
    }

    memo[n].emplace(key, result);
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> a >> b >> c;

    maskValue = (1 << 30) - 1;

    for (int i = 2; i <= MAX_VALUE; ++i) {
        if (composite[i]) {
            continue;
        }
        primes.push_back(i);
        for (int j = i; j <= MAX_VALUE; j += i) {
            composite[j] = true;
        }
    }

    reverse(primes.begin(), primes.end());
    memo.resize(primes.size());

    cout << f(a, b, c, 0) << '\n';
    return 0;
}

